out=collections.defaultdict(list)
for w,e in D.items():
  if not MARI.match(w) or w not in WL: continue
  g=e.get('g') or ''
  first=re.split(r'[;,(]',g)[0].strip()
  tok=first.split(' ')[0]
  # gloss like "мать материнский": first token = keyword
  for t,ks in K.items():
    if tok in ks.split():
      out[t].append((w,tok,e.get('hill'),e.get('loan')));break
for t,l in out.items(): print(t,len(l),' '.join(f'{w}={k}' for w,k,h,lo in l))
json.dump(out,open('/tmp/mined.json','w'),ensure_ascii=False)
